package com.kai.automusic;
import android.content.*;import android.graphics.*;import android.media.*;import android.net.Uri;import android.view.*;import java.nio.*;
public class DeckWave extends View{
 static final java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);
 final Paint p=new Paint(3); final SharedPreferences prefs; final boolean next; String uri=""; volatile float[] peaks; volatile long duration; volatile int generation; android.media.audiofx.Visualizer live; int session=-1; long lastAttempt; byte[] samples;
 public DeckWave(Context c,SharedPreferences prefs,boolean next){super(c);this.prefs=prefs;this.next=next;}
 public void track(String u){if(u.equals(uri))return;uri=u;peaks=null;duration=0;int g=++generation;if(u.isEmpty()||u.startsWith("https://"))return;pool.execute(()->decode(u,g));}
 void decode(String u,int g){MediaExtractor ex=new MediaExtractor();MediaCodec codec=null;try{ex.setDataSource(getContext(),Uri.parse(u),null);MediaFormat f=null;for(int i=0;i<ex.getTrackCount();i++){MediaFormat a=ex.getTrackFormat(i);if(a.getString(MediaFormat.KEY_MIME).startsWith("audio/")){f=a;ex.selectTrack(i);break;}}if(f==null)return;long dur=f.getLong(MediaFormat.KEY_DURATION);if(dur<=0)return;codec=MediaCodec.createDecoderByType(f.getString(MediaFormat.KEY_MIME));codec.configure(f,null,null,0);codec.start();float[] data=new float[512];boolean in=false,out=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(!out&&g==generation){if(!in){int k=codec.dequeueInputBuffer(10000);if(k>=0){ByteBuffer b=codec.getInputBuffer(k);int n=ex.readSampleData(b,0);if(n<0){codec.queueInputBuffer(k,0,0,0,4);in=true;}else{codec.queueInputBuffer(k,0,n,ex.getSampleTime(),0);ex.advance();}}}int k=codec.dequeueOutputBuffer(info,10000);if(k>=0){ByteBuffer b=codec.getOutputBuffer(k);if(b!=null&&info.size>1){b.order(ByteOrder.LITTLE_ENDIAN);int end=info.offset+info.size;float max=0;for(int j=info.offset;j+1<end;j+=2)max=Math.max(max,Math.abs((int)b.getShort(j))/32768f);int idx=(int)Math.max(0,Math.min(511,info.presentationTimeUs*512/dur));data[idx]=Math.max(data[idx],max);}out=(info.flags&4)!=0;codec.releaseOutputBuffer(k,false);}}if(g==generation){duration=dur/1000;peaks=data;postInvalidate();}}catch(Exception e){}finally{if(codec!=null)try{codec.release();}catch(Exception e){}ex.release();}}
 void capture(){int id=prefs.getInt("audioSession",-1);if(next||!prefs.getBoolean("playing",false))return;if(id!=session||(live==null&&android.os.SystemClock.elapsedRealtime()-lastAttempt>2000)){lastAttempt=android.os.SystemClock.elapsedRealtime();closeLive();session=id;if(id>0)try{live=new android.media.audiofx.Visualizer(id);live.setCaptureSize(android.media.audiofx.Visualizer.getCaptureSizeRange()[0]);samples=new byte[live.getCaptureSize()];live.setScalingMode(android.media.audiofx.Visualizer.SCALING_MODE_NORMALIZED);live.setEnabled(true);}catch(Exception e){closeLive();}}}void closeLive(){if(live!=null)try{live.release();}catch(Exception e){}live=null;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(0xff111820);c.drawRect(0,0,w,h,p);float[] a=peaks;int color=next?0xffeab308:0xff22d3ee;p.setColor(color);if(a!=null){for(int i=0;i<a.length;i++){float x=i*w/a.length,v=a[i]*h*.46f;c.drawLine(x,h/2-v,x,h/2+v,p);}float pos=prefs.getInt(next?"cueMs":"position",0);float x=Math.min(w,pos*w/Math.max(1,duration));p.setColor(0xffffffff);c.drawLine(x,0,x,h,p);}else{p.setTextSize(12*getResources().getDisplayMetrics().density);c.drawText(uri.isEmpty()?"—":"Waveform…",4,h*.65f,p);}if(!next){boolean playing=prefs.getBoolean("playing",false);capture();if(playing&&live!=null&&samples!=null)try{if(live.getWaveForm(samples)==0){p.setColor(0xfff8fafc);p.setStrokeWidth(1.5f);float last=h/2;for(int i=0;i<samples.length;i++){float y=h/2+Math.max(-h*.45f,Math.min(h*.45f,((samples[i]&255)-128)*h/64f));if(i>0)c.drawLine((i-1)*w/(samples.length-1),last,i*w/(samples.length-1),y,p);last=y;}}}catch(Exception e){}p.setColor(playing?0xff4ade80:0xfffacc15);p.setTextSize(12*getResources().getDisplayMetrics().density);c.drawText(playing?"PLAYING":"PAUSED",6,h-3,p);if(playing){float pulse=(float)(.5+.5*Math.sin(android.os.SystemClock.elapsedRealtime()/180.0));p.setAlpha(100+(int)(155*pulse));c.drawCircle(w-12,10,5,p);p.setAlpha(255);}}postInvalidateDelayed(50);}
 protected void onDetachedFromWindow(){generation++;closeLive();super.onDetachedFromWindow();}
}